head.script:
scwin.trigger1_onclick = function(e) {
    WebSquare.wUnit.getObjById('wfr1').setSrc("wframe_setSrc_order_WPFF-284_(WSQ-3668)_sub1.xml")
};
scwin.init = function() {
    console.log('wframe_setSrc_order_WPFF-284_(WSQ-3668)_sub2.xml');
    WebSquare.logger.printLog('wframe_setSrc_order_WPFF-284_(WSQ-3668)_sub2.xml');
};
scwin._checkLog = function() {
    var log = WebSquare.logger.getLog();
    return log.indexOf("wframe_setSrc_order_WPFF-284_(WSQ-3668)_sub2.xml") != -1;
}
scwin._checkLog2 = function() {
    var log = WebSquare.logger.getLog();
    return log.indexOf("wframe_setSrc_order_WPFF-284_(WSQ-3668)_sub1") != -1;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin._checkLog()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin._checkLog2()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
